        for k in 0..n-1:
            for l in 0..n-1:
                T[k][l] <- T[k][l] + x[k]*x[l]
    return T

function verify_covariance(n):
    T <- exact_covariance_kernel(n)
    for k in 0..n-1, l in 0..n-1:
        expected <- (2^n if k == l else 0)
        if T[k][l] != expected: return false
    return true

